const nav=(id,active='home')=>`<nav class="app-nav" aria-label="Navegação do app">${[['home','home','Início'],['orders','route','Rota'],['chats','chat','Chat'],['earnings','wallet','Ganhos'],['profile','user','Perfil']].map(([to,ic,label])=>`<button data-go="${to==='home'&&state.online?'online':to}" class="${active===to?'active':''}">${icon(ic)}<span>${label}</span>${to==='chats'?'<i class="nav-badge"></i>':''}</button>`).join('')}</nav>`;
const appButton=(label,action,ic='arrow',kind='primary',disabled=false)=>`<button class="${kind}" ${action.startsWith('go:')?`data-go="${action.slice(3)}"`:`data-action="${action}"`} ${disabled?'disabled':''}>${icon(ic)}<span>${label}</span></button>`;
const head=(title,subtitle='',back='home',right='')=>`<header class="app-header"><button class="app-icon back" data-go="${back==='home'&&state.online?'online':back}" aria-label="Voltar">${icon('back')}</button><div class="header-copy"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</header>`;
const page=(body,active='home',noNav=false,cls='')=>`<section class="app-page ${noNav?'no-nav':''} ${cls}">${!state.connected?`<div class="notice amber" style="margin-bottom:12px">${icon('offline')}Sem internet · seus envios aguardam conexão</div>`:''}${body}</section>${noNav?'':nav(state.screen,active)}`;
const badge=(text,ic='check',tone='')=>`<span class="pill ${tone}">${icon(ic)}${text}</span>`;
const section=(title,action='',to='')=>`<div class="section-head"><h2>${title}</h2>${action?`<button data-go="${to}">${action} ↗</button>`:''}</div>`;
const notice=(text,ic='shield',tone='')=>`<div class="notice ${tone}">${icon(ic)}<span>${text}</span></div>`;
const item=(title,sub,ic,to,extra='')=>`<button class="list-item" data-contact="${escapeHtml(title)}" ${to?`data-go="${to}"`:''}><span class="icon-tile">${icon(ic)}</span><span class="grow"><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</span>${extra||icon('chevron')}</button>`;
const pair=(label,value)=>`<div class="detail-pair"><span>${label}</span><strong>${value}</strong></div>`;
